head.script:
scwin.trigger3_onclick = function(e) {
    dataList1.removeAll();
};
scwin.getErrorLog = function() {
    var temp = WebSquare.logger.getErrorLog();
    return temp;
    // return temp.indexOf("error문구");
    // return temp.indexOf("error");
}
scwin.unitTest = function() {
    //Unit tets
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "1000");
    //Test step 1. treeview_removeAll_WPF-899_(WSQ-2248).xml 실행한다.- Execute treeview_removeAll_WPF-899_ (WSQ-2248) .xml.
    //Verify 1. treeview_removeAll_WPF-899_(WSQ-2248).xml 실행된다.-treeview_removeAll_WPF-899_ (WSQ-2248) .xml is executed.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById($p.id+'treeview2_label_1').innerText == 'test1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 2. test1 node를 선택한다. - 2. Select the test1 node.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById($p.id+'treeview2_label_1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 3. 3. 'dataList1.removeALL();' 버튼을 클릭하고 ctrl + 마우스우클릭 > 로그보기를 통해 정상로그를 확인한다.
    //3. 'dataList1.removeALL ();' Click the button and ctrl + right-click> View log to check the normal log.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 3. 3. 정상적으로 상단의 Tree내역이 삭제되고 로그보기에 에러없이 보여진다. (이전에는 로그보기 에러 발생함)
    //3. The top tree is deleted normally and the log view is displayed without error.(Previously there was a log view error)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'treeview2_label_1') == null", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.getErrorLog() == ''", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.jsonData = [{
            "label": "test1",
            "depth": "1",
            "value": "test1"
        },
        {
            "label": "test2",
            "depth": "2",
            "value": "test2"
        }
    ];
    dataList1.setJSON(jsonData);
    //Function unitTest
    //Create by Truong.Luu
    //Create date 18-Jan-2018
    // End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
